declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require MIZ_ROOT.'/app/pages.php';if(!installed())redirect('install.php');if(user())redirect();$error=null;$recovery=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf($_POST['_csrf']??null);if(site_settings()['registration_open']!=='1')fail(403,'REGISTRATION_CLOSED','ثبت‌نام تازه موقتاً بسته است.');rate_limit('registration',client_ip(),10,3600);$name=clean_name($_POST['name']??null);$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)fail(422,'EMAIL','ایمیل معتبر وارد کن.');$password=validate_password($_POST['password']??null);if($password!==($_POST['password_repeat']??''))fail(422,'PASSWORD','تکرار رمز یکسان نیست.');if(one('SELECT id FROM '.table('users').' WHERE email=?',[$email]))fail(422,'EMAIL','این ایمیل قابل ثبت نیست؛ اگر حساب داری وارد شو.');[$recovery,$hash]=new_recovery();$id=ident();query('INSERT INTO '.table('users').' (id,email,display_name,password_hash,recovery_hash,created_at) VALUES (?,?,?,?,?,?)',[$id,$email,$name,password_digest($password),$hash,now_ms()]);login_user(['id'=>$id,'session_version'=>1]);}catch(ApiError $e){$error=$e->getMessage();$recovery=null;}catch(Throwable $e){error_log('Miz signup failure '.$e->getCode());$error='ساخت حساب انجام نشد؛ ایمیل و اطلاعات را بررسی کن.';$recovery=null;}
page_start($recovery?'حساب تو آماده است.':'شروعِ مسیر تو.','حساب شخصی میز');if($recovery){message('ثبت‌نام انجام شد. کد بازیابی را همین حالا ذخیره کن.',true);echo '<p>با ایمیل و این کد می‌توانی رمز فراموش‌شده را عوض کنی. این کد فقط همین بار نمایش داده می‌شود؛ آن را به دیگران نده.</p><code class="recovery-code">'.e($recovery).'</code><a class="primary-button" href="'.e(url()).'">ورود به فضای مطالعه</a>';page_end();exit;}message($error);?><form method="post"><?php csrf_field();field('دوست داری چه صدایت کنیم؟','name','text',$_POST['name']??'','nickname');field('ایمیل','email','email',$_POST['email']??'','email');field('رمز عبور','password','password','','new-password');field('تکرار رمز عبور','password_repeat','password','','new-password');?><p class="setup-note">پس از ثبت‌نام، کد بازیابی اختصاصی دریافت می‌کنی.</p><button class="primary-button" type="submit">ساخت حساب میز</button></form><div class="account-links"><span>قبلاً حساب ساخته‌ای؟</span><a href="<?=e(url('login.php'))?>">ورود به حساب</a></div><?php page_end(); ?>
